namespace Fanex.Age.UI.Components.MatchByLeague
{

    public partial class MatchByLeague_Page : Fanex.Age.UI.TplPage
    {
        int _leagueId = 0;
        
        public override void RenderContent(HtmlTextWriter writer)
        {            
            DataTable MatchByGroup = View as DataTable;
            MatchByLeague_ContentMatch_Block tpl = new MatchByLeague_ContentMatch_Block();

            #region Match By Group
            if (MatchByGroup.Rows.Count > 0)
            {
                StringBuilder strGenMatch = new StringBuilder();
                StringBuilder strMatchSel = new StringBuilder();

                if (MatchByGroup.Rows.Count > 1)
                {                    
                    MatchByLeague_ContentMatch_ColMatch_Block ColMatch = new MatchByLeague_ContentMatch_ColMatch_Block();
                    ColMatch.Match = "All";
                    ColMatch.MatchName = "<b>" + Resources.Lang.all + "</b>";
                    ColMatch.checkAll = "onclick='CheckSelAllMatch()'";
                    strMatchSel.Append(ColMatch);
                }

                string matchId = string.Empty;
                DataRowCollection Rows = MatchByGroup.Rows;
                foreach (DataRow dr in Rows)
                {
                    MatchByLeague_ContentMatch_ColMatch_Block ColMatch = new MatchByLeague_ContentMatch_ColMatch_Block();
                    matchId = dr["matchid"].ToString();
                    ColMatch.Match = matchId;
                    ColMatch.MatchName = dr["matchname"].ToString();
                    ColMatch.checkAll = "onclick=isAllMatch('chL" + matchId + "')";
                    strMatchSel.Append(ColMatch);
                }

                tpl.ColMatch.SetValue(strMatchSel.ToString());
            }
            else
            {
                tpl.ColMatch.SetValue("<div class='no_info'>" + Resources.Lang.noInfo + "</div>");
            }
            #endregion

            writer.Write(tpl);
        }

        public override void ProcessRequest(ref System.Collections.Hashtable p)
        {
            _leagueId = Convert.ToInt32(Request["leagueid"]);
        }

        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            ForecastBO report = new ForecastBO(CurrentUserSession.NetSessionId);
            return report.GetMatchByLeague(_leagueId);
        }
    }
